#include <stdio.h>
#include <string.h>
int main() {
    char s[1005]; if (scanf("%s", s) != 1) return 0;
    int len = strlen(s);
    for (int i = 0; i + 1 < len; i += 2) {
        char tmp = s[i]; s[i] = s[i+1]; s[i+1] = tmp;
    }
    printf("%s\n", s);
    return 0;
}

