public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        if (sc.hasNext()) {
            char[] s = sc.next().toCharArray();
            for (int i = 0; i + 1 < s.length; i += 2) {
                char tmp = s[i]; s[i] = s[i+1]; s[i+1] = tmp;
            }
            System.out.println(new String(s));
        }
    }
}

