def main():
    toks = sys.stdin.read().split()
    if toks:
        s = list(toks[0])
        for i in range(0, len(s) - 1, 2): s[i], s[i+1] = s[i+1], s[i]
        print("".join(s))
if __name__ == "__main__": main()

